// Cross-language vector tests: the fixture ios/Tests/KeyrefCoreTests/
// Fixtures/vectors.json is generated by tools/vectordump (Go: circl HPKE +
// the shared proto module). Byte equality here proves the Swift core
// interprets docs/protocol.md exactly like the Go reference — this is the
// design §9.2 跨语言测试向量 anchor.
import CryptoKit
import XCTest

@testable import KeyrefCore

// MARK: - fixture decoding

private struct VectorFile: Decodable, Sendable {
    struct InfoVector: Decodable {
        struct Input: Decodable {
            let purpose: String
            let vault_id: String
            let recipient_device_id: String
        }
        let input: Input
        let info_hex: String
    }

    struct OneTimeInfoVector: Decodable {
        let vault_id: String
        let recipient_device_id: String
        let item_id: String
        let approval_id: String
        let request_ciphertext_hex: String
        let info_hex: String
    }

    struct AADVector: Decodable {
        let vault_id: String
        let item_id: String
        let device_id: String
        let secret_hex: String
        let meta_hex: String
        let vault_meta_key_hex: String
        let vault_item_key_hex: String
        let recovery_hex: String
        let audit_hex: String
        let secret_wrong_item_hex: String
        let secret_wrong_vault_hex: String
    }

    struct AEADVector: Decodable {
        let key_hex: String
        let aad_hex: String
        let nonce_hex: String
        let plaintext_hex: String
        let blob_hex: String
    }

    struct HPKEVector: Decodable {
        let kem: String
        let recipient_private_hex: String
        let recipient_public_hex: String
        let info_hex: String
        let encapsulation_seed_hex: String
        let plaintext_hex: String
        let enc_hex: String
        let ct_hex: String
    }

    struct RecoveryVector: Decodable {
        let vault_id_hex: String
        let seed_hex: String
        let code: String
        let kek_hex: String
        let sign_public_hex: String
        let kdf_json: String
        let recovery_wrap_hex: String
        let vmk_hex: String
        let recovery_aad_hex: String
    }

    struct GrantFields: Decodable {
        let device_id: String
        let item_id: String
        let kind: String
        let hpke_enc: String
        let wrapped_key: String
        let expires_at: UInt64
        let revision: UInt64
    }

    struct DirDeviceFields: Decodable {
        let device_id: String
        let kind: String
        let status: String
        let hpke_kem: String
        let hpke_public_key_hex: String
        let sign_alg: String
        let sign_public_key_hex: String
        let renewal_sign_public_key_hex: String
        let grants_digest_hex: String
    }

    struct DirectoryFields: Decodable {
        let vault_id: String
        let directory_revision: UInt64
        let devices: [DirDeviceFields]
    }

    struct PairFields: Decodable {
        let vault_id: String
        let owner_sign_public_hex: String
        let nonce: String
        let device_id: String
        let hpke_kem: String
        let hpke_public_key_hex: String
        let sign_alg: String
        let sign_public_key_hex: String
        let label: String
        let grant_count: Int
    }

    struct ItemFields: Decodable {
        let vault_id: String
        let item_id: String
        let revision: UInt64
        let meta_ciphertext_hex: String
        let secret_ciphertext_hex: String
        let vault_wrapped_meta_key_hex: String
        let vault_wrapped_item_key_hex: String
        let writer_device_id: String
    }

    struct SimpleFields: Decodable {
        let vault_id: String?
        let device_id: String?
        let challenge_hex: String?
        let nonce_raw_hex: String?
        let proposed_name: String?
        let recovery_wrap_hex: String?
        let kdf_json: String?
        let recovery_sign_pub_hex: String?
        let owner_signature_hex: String?
        let recovery_signature_hex: String?
    }

    struct TranscriptVector: Decodable {
        // The structured `fields` object is decoded per-transcript type;
        // keep the raw form here for generic assertions.
        let fields: RawJSON
        let bytes_hex: String
        let signature_hex: String
        let sign_alg: String
        let signer_public_hex: String
        let tampered_bytes_hex: String?
        let tampered_index: Int?
    }

    struct RawJSON: Decodable, Sendable {
        subscript(key: String) -> RawJSONValue? {
            dict[key]
        }
        let dict: [String: RawJSONValue]
        init(from decoder: Decoder) throws {
            let c = try decoder.singleValueContainer()
            dict = try c.decode([String: RawJSONValue].self)
        }
    }

    enum RawJSONValue: Decodable, Sendable {
        case string(String)
        case number(UInt64)
        case object([String: RawJSONValue])
        case array([RawJSONValue])

        init(from decoder: Decoder) throws {
            let c = try decoder.singleValueContainer()
            if let s = try? c.decode(String.self) { self = .string(s); return }
            if let n = try? c.decode(UInt64.self) { self = .number(n); return }
            if let o = try? c.decode([String: RawJSONValue].self) { self = .object(o); return }
            if let a = try? c.decode([RawJSONValue].self) { self = .array(a); return }
            throw DecodingError.dataCorruptedError(in: c, debugDescription: "unsupported JSON value")
        }

        var stringValue: String? { if case .string(let s) = self { return s }; return nil }
        var numberValue: UInt64? { if case .number(let n) = self { return n }; return nil }
    }

    let generator: String
    let vault_id: String
    let owner_device_id: String
    let cli_device_id: String
    let item_id: String
    let other_item_id: String
    let approval_id: String
    let owner_sign_public_hex: String
    let cli_sign_public_hex: String

    let info_item_key: InfoVector
    let info_one_time: OneTimeInfoVector
    let aad: AADVector
    let aead_blob: AEADVector
    let hpke_p256: HPKEVector
    let hpke_x25519: HPKEVector
    let recovery: RecoveryVector

    let item_transcript: TranscriptVector
    let grant_view_transcript: TranscriptVector
    let grant_use_transcript: TranscriptVector
    let grant_delete_transcript: TranscriptVector
    let directory_transcript: TranscriptVector
    let pair_transcript: TranscriptVector
    let pair_register_transcript: TranscriptVector
    let session_transcript: TranscriptVector
    let vault_delete_transcript: TranscriptVector
    let vault_recovery_transcript: TranscriptVector

    let owner_session_signature_hex: String
    let cli_grants_digest_hex: String
    let empty_grants_digest_hex: String
}

final class VectorTests: XCTestCase {
    private static let vectors: VectorFile = {
        let url = Bundle.module.url(forResource: "vectors", withExtension: "json", subdirectory: "Fixtures")
            ?? Bundle.module.url(forResource: "vectors", withExtension: "json")
        guard let url else {
            fatalError("vectors.json fixture missing from test resources")
        }
        let data = try! Data(contentsOf: url)
        return try! WireJSON.decoder.decode(VectorFile.self, from: data)
    }()

    private var v: VectorFile { Self.vectors }

    private func hex(_ s: String, file: StaticString = #filePath, line: UInt = #line) -> Data {
        do {
            return try KeyrefEncoding.hexDecode(s)
        } catch {
            XCTFail("bad hex in fixture: \(s.prefix(24))…", file: file, line: line)
            return Data()
        }
    }

    // MARK: info strings (§3.7)

    func testInfoItemKey() throws {
        let i = v.info_item_key
        let got = try hpkeInfo(purpose: i.input.purpose, vaultID: i.input.vault_id,
                               recipientDeviceID: i.input.recipient_device_id)
        XCTAssertEqual(got, hex(i.info_hex))
    }

    func testInfoOneTimeItemKey() throws {
        let i = v.info_one_time
        let got = try oneTimeItemKeyInfo(vaultID: i.vault_id, recipientDeviceID: i.recipient_device_id,
                                         itemID: i.item_id, approvalID: i.approval_id,
                                         requestCiphertext: hex(i.request_ciphertext_hex))
        XCTAssertEqual(got, hex(i.info_hex))
        // D4: the one-time info extends the base with item/approval/digest.
        let base = try hpkeInfo(purpose: KeyrefPurpose.oneTimeItemKey, vaultID: i.vault_id,
                                recipientDeviceID: i.recipient_device_id)
        XCTAssertTrue(got.starts(with: base))
    }

    // MARK: AADs (§3.7)

    func testAADs() throws {
        let a = v.aad
        XCTAssertEqual(try secretAAD(vaultID: a.vault_id, itemID: a.item_id), hex(a.secret_hex))
        XCTAssertEqual(try metaAAD(vaultID: a.vault_id, itemID: a.item_id), hex(a.meta_hex))
        XCTAssertEqual(try vaultWrappedMetaKeyAAD(vaultID: a.vault_id, itemID: a.item_id), hex(a.vault_meta_key_hex))
        XCTAssertEqual(try vaultWrappedItemKeyAAD(vaultID: a.vault_id, itemID: a.item_id), hex(a.vault_item_key_hex))
        XCTAssertEqual(try recoveryAAD(vaultID: a.vault_id), hex(a.recovery_hex))
        XCTAssertEqual(try auditAAD(vaultID: a.vault_id, deviceID: a.device_id), hex(a.audit_hex))
        // Negative: the secret AAD for a different item / vault differs.
        XCTAssertNotEqual(hex(a.secret_hex), hex(a.secret_wrong_item_hex))
        XCTAssertNotEqual(hex(a.secret_hex), hex(a.secret_wrong_vault_hex))
    }

    // MARK: AEAD blob (§1.5)

    func testAEADBlob() throws {
        let b = v.aead_blob
        let blob = try BlobCrypto.sealBlob(key: hex(b.key_hex), aad: hex(b.aad_hex),
                                           plaintext: hex(b.plaintext_hex), nonce: hex(b.nonce_hex))
        XCTAssertEqual(blob, hex(b.blob_hex))
        XCTAssertEqual(try BlobCrypto.openBlob(key: hex(b.key_hex), aad: hex(b.aad_hex), blob: hex(b.blob_hex)),
                       hex(b.plaintext_hex))
        // Negative: wrong AAD must not authenticate.
        XCTAssertThrowsError(try BlobCrypto.openBlob(key: hex(b.key_hex), aad: hex(v.aad.secret_wrong_item_hex),
                                                     blob: hex(b.blob_hex)))
    }

    func testAEADBlobWrongKeyFails() throws {
        let b = v.aead_blob
        var wrong = hex(b.key_hex)
        wrong[wrong.startIndex] ^= 0x01
        XCTAssertThrowsError(try BlobCrypto.openBlob(key: wrong, aad: hex(b.aad_hex), blob: hex(b.blob_hex)))
    }

    func testSecretBlobWrongAADFails() throws {
        // Re-seal the vector secret under the real AAD, then try the AAD
        // that names another item and another vault — both must fail (the
        // 正反例 of the task).
        let a = v.aad
        let ct = try BlobCrypto.sealBlob(key: hex(v.aead_blob.key_hex), aad: hex(a.secret_hex),
                                         plaintext: Data("x".utf8))
        XCTAssertThrowsError(try BlobCrypto.openBlob(key: hex(v.aead_blob.key_hex), aad: hex(a.secret_wrong_item_hex), blob: ct))
        XCTAssertThrowsError(try BlobCrypto.openBlob(key: hex(v.aead_blob.key_hex), aad: hex(a.secret_wrong_vault_hex), blob: ct))
    }

    // MARK: HPKE (receiver path — Go/circl seals, Swift opens)

    func testHPKEX25519Receiver() throws {
        let h = v.hpke_x25519
        XCTAssertEqual(h.kem, "X25519")
        let pt = try KeyrefHPKE.unwrapKey(kemName: KEMName.x25519,
                                          privateKey: hex(h.recipient_private_hex),
                                          info: hex(h.info_hex),
                                          enc: hex(h.enc_hex), ct: hex(h.ct_hex))
        XCTAssertEqual(pt, hex(h.plaintext_hex))
        XCTAssertEqual(hex(h.enc_hex).count, KeyrefSizes.x25519Key)
    }

    func testHPKEP256Receiver() throws {
        let h = v.hpke_p256
        XCTAssertEqual(h.kem, "P-256")
        let pt = try KeyrefHPKE.unwrapKey(kemName: KEMName.p256,
                                          privateKey: hex(h.recipient_private_hex),
                                          info: hex(h.info_hex),
                                          enc: hex(h.enc_hex), ct: hex(h.ct_hex))
        XCTAssertEqual(pt, hex(h.plaintext_hex))
        XCTAssertEqual(hex(h.enc_hex).count, KeyrefSizes.p256Key)
    }

    func testHPKEWrongInfoFails() throws {
        let h = v.hpke_x25519
        var info = hex(h.info_hex)
        info[info.count - 1] ^= 0x01
        XCTAssertThrowsError(try KeyrefHPKE.unwrapKey(kemName: KEMName.x25519,
                                                      privateKey: hex(h.recipient_private_hex),
                                                      info: info, enc: hex(h.enc_hex), ct: hex(h.ct_hex)))
    }

    func testHPKESenderRoundtrip() throws {
        // Sender path: Swift seals to the fixture recipients' public keys
        // and its own receiver opens. (Cross-language sender verification:
        // CryptoKit-produced envelopes were verified to open under circl
        // via tools/vectordump -check-seal; see the dev log in the report.)
        for h in [v.hpke_x25519, v.hpke_p256] {
            let kem = h.kem
            let (enc, ct) = try KeyrefHPKE.wrapKey(kemName: kem,
                                                   recipientPublicKey: hex(h.recipient_public_hex),
                                                   info: hex(h.info_hex),
                                                   plaintext: hex(h.plaintext_hex))
            let pt = try KeyrefHPKE.unwrapKey(kemName: kem,
                                              privateKey: hex(h.recipient_private_hex),
                                              info: hex(h.info_hex), enc: enc, ct: ct)
            XCTAssertEqual(pt, hex(h.plaintext_hex), kem)
            XCTAssertEqual(enc.count, kem == KEMName.x25519 ? 32 : 65, kem)
        }
    }

    // MARK: recovery (§3.8)

    func testRecoveryDerivationAndCode() throws {
        let r = v.recovery
        let payload = hex(r.vault_id_hex) + hex(r.seed_hex)
        XCTAssertEqual(RecoveryCode.encode(payload: payload), r.code)

        let parsed = try RecoveryCode.decode(r.code)
        XCTAssertEqual(parsed.vaultID, r.vault_id_hex)
        XCTAssertEqual(parsed.seed, hex(r.seed_hex))

        let keys = try RecoveryKeys.derive(fromSeed: hex(r.seed_hex))
        XCTAssertEqual(keys.kek, hex(r.kek_hex))
        XCTAssertEqual(keys.signer.signPublicKey, hex(r.sign_public_hex))

        // recovery_wrap opens with the derived KEK to the vector VMK.
        let vmk = try RecoveryKeys.unwrapVMK(keys: keys, recoveryWrap: hex(r.recovery_wrap_hex),
                                             vaultID: r.vault_id_hex)
        XCTAssertEqual(vmk, hex(r.vmk_hex))
        XCTAssertEqual(try recoveryAAD(vaultID: r.vault_id_hex), hex(r.recovery_aad_hex))
        XCTAssertEqual(RecoveryKeys.defaultKDFJSON, r.kdf_json)
    }

    func testRecoveryCodeWrongSeedFails() throws {
        let r = v.recovery
        var badSeed = hex(r.seed_hex)
        badSeed[badSeed.startIndex] ^= 0x01
        let keys = try RecoveryKeys.derive(fromSeed: badSeed)
        XCTAssertThrowsError(try RecoveryKeys.unwrapVMK(keys: keys,
                                                        recoveryWrap: hex(r.recovery_wrap_hex),
                                                        vaultID: r.vault_id_hex))
    }

    // MARK: transcripts — rebuild bytes and verify signatures (§3)

    func testItemTranscript() throws {
        let t = v.item_transcript
        XCTAssertEqual(t.sign_alg, SignAlg.ecdsaP256)
        let f = t.fields
        let tr = ItemTranscript(
            vaultID: f["vault_id"]?.stringValue ?? "", itemID: f["item_id"]?.stringValue ?? "",
            revision: f["revision"]?.numberValue ?? 0,
            metaCiphertext: hex(f["meta_ciphertext_hex"]?.stringValue ?? ""),
            secretCiphertext: hex(f["secret_ciphertext_hex"]?.stringValue ?? ""),
            vaultWrappedMetaKey: hex(f["vault_wrapped_meta_key_hex"]?.stringValue ?? ""),
            vaultWrappedItemKey: hex(f["vault_wrapped_item_key_hex"]?.stringValue ?? ""),
            writerDeviceID: f["writer_device_id"]?.stringValue ?? "")
        let bytes = try tr.buildBytes()
        XCTAssertEqual(bytes, hex(t.bytes_hex))
        try verifyOwnerSignature(transcript: bytes, signature: hex(t.signature_hex),
                                 ownerSignPublicKey: hex(t.signer_public_hex))
        // Tampered bytes must fail (fail-closed anchor).
        XCTAssertThrowsError(try verifyOwnerSignature(transcript: hex(t.tampered_bytes_hex ?? ""),
                                                      signature: hex(t.signature_hex),
                                                      ownerSignPublicKey: hex(t.signer_public_hex)))
    }

    private func grantTranscript(_ t: VectorFile.TranscriptVector) throws -> (GrantTranscript, Data) {
        let f = t.fields
        let g = GrantTranscript(
            vaultID: v.vault_id,
            deviceID: f["device_id"]?.stringValue ?? "",
            itemID: f["item_id"]?.stringValue ?? "",
            kind: f["kind"]?.stringValue ?? "",
            revision: f["revision"]?.numberValue ?? 0,
            expiresAt: f["expires_at"]?.numberValue ?? 0,
            hpkeEnc: hex(f["hpke_enc"]?.stringValue ?? ""),
            wrappedKey: hex(f["wrapped_key"]?.stringValue ?? ""))
        return (g, try g.buildBytes())
    }

    func testGrantTranscripts() throws {
        for (vec, name) in [(v.grant_view_transcript, "view"),
                            (v.grant_use_transcript, "use"),
                            (v.grant_delete_transcript, "delete")] {
            let (g, bytes) = try grantTranscript(vec)
            XCTAssertEqual(bytes, hex(vec.bytes_hex), name)
            try verifyOwnerSignature(transcript: bytes, signature: hex(vec.signature_hex),
                                     ownerSignPublicKey: hex(vec.signer_public_hex))
        }
        // The deletion form has empty crypto fields and expires_at 0.
        let f = v.grant_delete_transcript.fields
        XCTAssertEqual(f["hpke_enc"]?.stringValue ?? "", "")
        XCTAssertEqual(f["expires_at"]?.numberValue ?? 1, 0)
    }

    func testDirectoryTranscript() throws {
        let t = v.directory_transcript
        let f = t.fields
        var devices: [DirectoryDevice] = []
        if case .array(let arr) = f["devices"] {
            for d in arr {
                guard case .object(let obj) = d else { XCTFail("device must be object"); continue }
                devices.append(DirectoryDevice(
                    deviceID: obj["device_id"]?.stringValue ?? "",
                    kind: obj["kind"]?.stringValue ?? "",
                    status: obj["status"]?.stringValue ?? "",
                    hpkeKEM: obj["hpke_kem"]?.stringValue ?? "",
                    hpkePublicKey: hex(obj["hpke_public_key_hex"]?.stringValue ?? ""),
                    signAlg: obj["sign_alg"]?.stringValue ?? "",
                    signPublicKey: hex(obj["sign_public_key_hex"]?.stringValue ?? ""),
                    renewalSignPublicKey: hex(obj["renewal_sign_public_key_hex"]?.stringValue ?? ""),
                    grantsDigest: hex(obj["grants_digest_hex"]?.stringValue ?? ""),
                    // One raw byte after the digest (design v0.8 §14.4):
                    // the vector must round-trip it or the bytes diverge.
                    receiverRole: UInt8(obj["receiver_role"]?.numberValue ?? 0)))
            }
        }
        let dir = DirectoryTranscript(vaultID: f["vault_id"]?.stringValue ?? "",
                                      directoryRevision: f["directory_revision"]?.numberValue ?? 0,
                                      devices: devices)
        let bytes = try dir.buildBytes()
        XCTAssertEqual(bytes, hex(t.bytes_hex))
        try verifyOwnerSignature(transcript: bytes, signature: hex(t.signature_hex),
                                 ownerSignPublicKey: hex(t.signer_public_hex))
        XCTAssertThrowsError(try verifyOwnerSignature(transcript: hex(t.tampered_bytes_hex ?? ""),
                                                      signature: hex(t.signature_hex),
                                                      ownerSignPublicKey: hex(t.signer_public_hex)))
    }

    func testPairTranscript() throws {
        let t = v.pair_transcript
        let f = t.fields
        // Rebuild the grants from the grant vectors (same fixtures).
        let grants = try [v.grant_view_transcript, v.grant_use_transcript].map { vec -> GrantTranscript in
            try grantTranscript(vec).0
        }
        let tr = PairTranscript(
            vaultID: f["vault_id"]?.stringValue ?? "",
            ownerSignPublicKey: hex(f["owner_sign_public_hex"]?.stringValue ?? ""),
            nonce: f["nonce"]?.stringValue ?? "",
            deviceID: f["device_id"]?.stringValue ?? "",
            hpkeKEM: f["hpke_kem"]?.stringValue ?? "",
            hpkePublicKey: hex(f["hpke_public_key_hex"]?.stringValue ?? ""),
            signAlg: f["sign_alg"]?.stringValue ?? "",
            signPublicKey: hex(f["sign_public_key_hex"]?.stringValue ?? ""),
            label: f["label"]?.stringValue ?? "",
            grants: grants)
        let bytes = try tr.buildBytes()
        XCTAssertEqual(bytes, hex(t.bytes_hex))
        XCTAssertEqual(grants.count, Int(f["grant_count"]?.numberValue ?? 999))
        try verifyOwnerSignature(transcript: bytes, signature: hex(t.signature_hex),
                                 ownerSignPublicKey: hex(t.signer_public_hex))
    }

    func testPairRegisterTranscript() throws {
        let t = v.pair_register_transcript
        let f = t.fields
        let bytes = try buildPairRegisterTranscript(nonce: hex(f["nonce_raw_hex"]?.stringValue ?? ""),
                                                    proposedName: f["proposed_name"]?.stringValue ?? "")
        XCTAssertEqual(bytes, hex(t.bytes_hex))
        XCTAssertEqual(t.sign_alg, SignAlg.ed25519)
        try verifyCLISignature(transcript: bytes, signature: hex(t.signature_hex),
                               cliSignPublicKey: hex(t.signer_public_hex))
    }

    func testSessionTranscript() throws {
        let t = v.session_transcript
        let f = t.fields
        let bytes = try buildSessionTranscript(deviceID: f["device_id"]?.stringValue ?? "",
                                               challenge: hex(f["challenge_hex"]?.stringValue ?? ""))
        XCTAssertEqual(bytes, hex(t.bytes_hex))
        try verifyCLISignature(transcript: bytes, signature: hex(t.signature_hex),
                               cliSignPublicKey: hex(t.signer_public_hex))
        // The owner also signs session transcripts (iOS owner session).
        try verifyOwnerSignature(transcript: bytes, signature: hex(v.owner_session_signature_hex),
                                 ownerSignPublicKey: hex(v.owner_sign_public_hex))
    }

    func testVaultDeleteTranscript() throws {
        let t = v.vault_delete_transcript
        let f = t.fields
        let bytes = try buildVaultDeleteTranscript(vaultID: f["vault_id"]?.stringValue ?? "",
                                                   challenge: hex(f["challenge_hex"]?.stringValue ?? ""))
        XCTAssertEqual(bytes, hex(t.bytes_hex))
        try verifyOwnerSignature(transcript: bytes, signature: hex(t.signature_hex),
                                 ownerSignPublicKey: hex(t.signer_public_hex))
    }

    func testVaultRecoveryTranscript() throws {
        let t = v.vault_recovery_transcript
        let f = t.fields
        let bytes = try buildVaultRecoveryTranscript(vaultID: f["vault_id"]?.stringValue ?? "",
                                                     recoveryWrap: hex(f["recovery_wrap_hex"]?.stringValue ?? ""),
                                                     recoveryKDFJSON: f["kdf_json"]?.stringValue ?? "",
                                                     recoverySignPub: hex(f["recovery_sign_pub_hex"]?.stringValue ?? ""))
        XCTAssertEqual(bytes, hex(t.bytes_hex))
        try verifyOwnerSignature(transcript: bytes, signature: hex(f["owner_signature_hex"]?.stringValue ?? ""),
                                 ownerSignPublicKey: hex(v.owner_sign_public_hex))
        // Both signatures (§6.3/D13) cover the same bytes; the recovery
        // authority's public key is the §3.8 derivation output.
        let keys = try RecoveryKeys.derive(fromSeed: hex(v.recovery.seed_hex))
        try verifyRecoverySignature(transcript: bytes, signature: hex(f["recovery_signature_hex"]?.stringValue ?? ""),
                                    recoverySignPub: keys.signer.signPublicKey)
        XCTAssertThrowsError(try verifyOwnerSignature(transcript: hex(t.tampered_bytes_hex ?? ""),
                                                      signature: hex(t.signature_hex),
                                                      ownerSignPublicKey: hex(t.signer_public_hex)))
    }

    // MARK: grants digest (§3.3, D6)

    func testGrantsDigest() throws {
        let view = try grantTranscript(v.grant_view_transcript).0
        let use = try grantTranscript(v.grant_use_transcript).0
        // Ordering: (item_id asc, kind byte asc) — "use" before "view".
        let digest = try grantsDigest([view, use])
        XCTAssertEqual(digest, hex(v.cli_grants_digest_hex))
        // Order independence of the input list.
        XCTAssertEqual(try grantsDigest([use, view]), digest)
        XCTAssertEqual(emptyGrantsDigest(), hex(v.empty_grants_digest_hex))
        XCTAssertNotEqual(digest, emptyGrantsDigest())
    }

    // MARK: full owner roundtrip over the vector item row

    func testVectorItemRowDecrypts() throws {
        let t = v.item_transcript
        let f = t.fields
        // The view grant wraps the meta key; the item row's meta
        // ciphertext decrypts under it.
        let viewGrant = try grantTranscript(v.grant_view_transcript).0
        let metaKey = try ItemCrypto.unwrapGrantKey(
            kemName: KEMName.x25519,
            receiver: .x25519(try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: hex(v.hpke_x25519.recipient_private_hex))),
            grantKind: viewGrant.kind, vaultID: v.vault_id, deviceID: viewGrant.deviceID,
            hpkeEnc: viewGrant.hpkeEnc, wrappedKey: viewGrant.wrappedKey)
        let metaCT = hex(f["meta_ciphertext_hex"]?.stringValue ?? "")
        let meta = try ItemCrypto.openMeta(key: metaKey, blob: metaCT,
                                           vaultID: v.vault_id, itemID: v.item_id)
        XCTAssertEqual(meta.ref, "openai-prod")
        XCTAssertEqual(meta.masked, "sk-****abcd")

        // The use grant wraps the item key; the secret opens under it.
        let itemKey = hex(v.hpke_x25519.plaintext_hex)
        let secret = try ItemCrypto.openSecret(key: itemKey,
                                               blob: hex(f["secret_ciphertext_hex"]?.stringValue ?? ""),
                                               vaultID: v.vault_id, itemID: v.item_id)
        XCTAssertTrue(secret.value.hasPrefix("sk-VECTOR-PLAINTEXT"))
    }

    func testVectorGrantUnwraps() throws {
        // Unwrap the view grant exactly as a receiving device would; the
        // unwrapped meta key must then open the item row's meta ciphertext.
        let grant = try grantTranscript(v.grant_view_transcript).0
        let metaKey = try ItemCrypto.unwrapGrantKey(
            kemName: KEMName.x25519,
            receiver: .x25519(try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: hex(v.hpke_x25519.recipient_private_hex))),
            grantKind: grant.kind, vaultID: v.vault_id, deviceID: grant.deviceID,
            hpkeEnc: grant.hpkeEnc, wrappedKey: grant.wrappedKey)
        let meta = try ItemCrypto.openMeta(key: metaKey,
                                           blob: hex(v.item_transcript.fields["meta_ciphertext_hex"]?.stringValue ?? ""),
                                           vaultID: v.vault_id, itemID: v.item_id)
        XCTAssertEqual(meta.ref, "openai-prod")
    }
}
